# 信任校准计算器: 分类 -> 通过率 -> 建议级别(含样本不足保护)
def level_of(rate):
    if rate >= 0.9:
        return 3
    if rate >= 0.7:
        return 2
    if rate >= 0.5:
        return 1
    return 0

def calibrate(records):
    stats = {}
    for ttype, first_pass in records:
        n, ok = stats.get(ttype, (0, 0))
        stats[ttype] = (n + 1, ok + (1 if first_pass else 0))
    return stats

